import {loadGuidedExams} from './workshop-guided-exam-model.mjs';
import {guidedExamMastery,guidedCaseErrors} from './workshop-guided-exam-history.mjs';
import {repairExamTotal} from './workshop-repair-exam-history.mjs';
import {repairExamGrade} from './workshop-repair-exam-model.mjs';
import {caseInfo} from './workshop-content.mjs';
import {alternate} from './workshop-challenges.mjs';
export function mountGuidedExamHistory({language,hidden,review,retry}){
 const root=document.createElement('section');root.id='guidedExamHistory';root.className='challenge-panel';document.querySelector('main').append(root);
 const t=(es,en)=>language()==='es'?es:en,name=(kind,id)=>(id==='primary'?caseInfo[kind].fix:alternate[kind].fix)[language()];
 function render(){root.hidden=hidden();if(root.hidden)return;root.replaceChildren();const add=(tag,text,parent=root)=>{const el=document.createElement(tag);el.textContent=text;parent.append(el);return el;};add('h2',t('Historial de exámenes guiados','Guided exam history'));let rows;try{rows=loadGuidedExams(localStorage).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished));}catch{add('p',t('No se pudo leer el historial. Recarga para reintentar.','Could not read history. Reload to retry.'));return;}add('p',t('Últimos 25 exámenes completados en este navegador. Los repasos se guardan como prácticas guiadas y no cambian tus notas originales.','Latest 25 completed exams in this browser. Retries are saved as guided practices and do not change your original grades.'));if(!rows.length){add('p',t('Completa un examen para comparar tus resultados.','Complete an exam to compare your results.'));return;}
 const first=repairExamTotal(rows[0]),latest=repairExamTotal(rows.at(-1));add('p',t('Primera nota: ','First score: ')+first+'/100 · '+t('Última: ','Latest: ')+latest+'/100 · '+t('Cambio: ','Change: ')+(latest-first>0?'+':'')+(latest-first));
 const table=add('table','');table.className='guided-exam-scores';add('caption',t('Comparación de notas · cada examen conserva sus casos y dificultad','Score comparison · each exam retains its cases and difficulty'),table);const head=add('tr','',add('thead','',table));for(const text of [t('Fecha','Date'),t('Nota','Score'),t('Cambio anterior','Previous change')])add('th',text,head).scope='col';const body=add('tbody','',table);for(const [i,e]of rows.entries()){const tr=add('tr','',body);add('td',new Date(e.finished).toLocaleDateString(language(),{timeZone:'America/Bogota'}),tr);add('td',repairExamTotal(e)+'/100',tr);const delta=i?repairExamTotal(e)-repairExamTotal(rows[i-1]):null;add('td',delta===null?'—':(delta>0?'+':'')+delta,tr);}
 add('h3',t('Dominio por intervención','Progress by intervention'));add('p',t('Consolidada = tres casos recientes sin elecciones innecesarias, causas pendientes ni pruebas posteriores faltantes. Cada caso cuenta una vez; distintos niveles no son directamente equivalentes.','Consistent = three recent cases without unnecessary choices, remaining causes or missing post-repair tests. Each case counts once; different difficulty levels are not directly equivalent.'));
 const button=(label,host,action)=>{const b=add('button',label,host);b.onclick=action;return b;};
 for(const g of guidedExamMastery(rows)){const card=add('article','');card.className='repair-progress-card';add('h4',name(g.kind,g.id),card);add('p',g.correct+'/'+g.total+t(' casos sin errores · ',' clean cases · ')+g.recent+'/3 '+t('recientes · ','recent · ')+(g.mastered?t('Consolidada','Consistent'):t('En práctica','Developing')),card);const meter=add('meter','',card);meter.min=0;meter.max=g.total;meter.value=g.correct;meter.setAttribute('aria-label',g.correct+'/'+g.total+t(' casos sin errores',' clean cases'));if(g.lastError){const c=g.lastError;button(t('Repasar esta intervención','Review this intervention'),card,()=>retry(c.exam,c.index,g.id)).dataset.masteryRetry=g.key;}}
 add('h3',t('Exámenes y decisiones','Exams and decisions'));add('p',t('El repaso reinicia el caso original para practicar la intervención elegida; no es una repetición a ciegas. La comparación reproduce tus decisiones originales paso a paso.','Practice restarts the original case to focus on the selected intervention; it is not a blind retest. Comparison replays your original decisions step by step.'));
 for(const e of [...rows].reverse()){const details=add('details','');add('summary',new Date(e.finished).toLocaleString(language(),{timeZone:'America/Bogota'})+' · '+repairExamTotal(e)+'/100',details);for(const [index,c]of e.cases.entries()){const card=add('article','',details);add('h4',caseInfo[c.repair.kind].title[language()]+' · '+repairExamGrade(c).score+'/100',card);button(t('Comparar decisiones en 3D','Compare decisions in 3D'),card,()=>review(e,index)).dataset.examCompare=index;const errors=guidedCaseErrors(c);if(!errors.length)add('p',t('Sin errores registrados.','No recorded errors.'),card);for(const err of errors){add('p',name(c.repair.kind,err.id)+' · '+[err.unnecessary?t('Innecesaria o repetida','Unnecessary or repeated'):null,err.missing?t('Causa pendiente','Remaining cause'):null,err.measurements?t('Faltan pruebas posteriores','Missing post-repair tests'):null].filter(Boolean).join(' · '),card);button(t('Practicar esta decisión','Practise this decision'),card,()=>retry(e,index,err.id)).dataset.examRetry=c.repair.kind+':'+err.id;}}}
 }
 return {render};
}
